// Extract a bounded Vuex module — do not clone the root.
export const useCartStore = defineStore('cart', {
  state: () => ({ lines: [] as CartLine[] }),
  actions: {
    add(line: CartLine) {
      this.lines.push(line)
    },
  },
})

// Cross-talk during the transition only.
async function addFromLegacy() {
  const cart = useCartStore()
  cart.add(await useVuexStore().dispatch('cart/peek'))
}

